(function(root){
const L=typeof module!=='undefined'?require('./vendor/lunar.js'):root;
const C=typeof module!=='undefined'?require('./content.js'):root.FortuneContent;
const elementName=['목','화','토','금','수'];
function today(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
function parseDate(s){if(typeof s!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(s))throw Error('날짜를 정확히 입력해주세요.');const [y,m,d]=s.split('-').map(Number);const dt=new Date(Date.UTC(y,m-1,d));if(y<1900||s>today()||dt.getUTCFullYear()!==y||dt.getUTCMonth()+1!==m||dt.getUTCDate()!==d)throw Error('1900년부터 오늘까지의 실제 날짜를 입력해주세요.');return [y,m,d];}
function calc(s){const a=parseDate(s),l=L.Solar.fromYmd(...a).getLunar();const stem=l.getDayGanIndex(),branch=l.getDayZhiIndex();return{stem,branch,element:Math.floor(stem/2),pillar:l.getDayInGanZhi(),label:C.stems[stem][0]};}
function pet({name,date,mode='birth'}){if(!['birth','adoption'].includes(mode))throw Error('날짜 종류를 확인해주세요.');name=(name||'우리 아이').trim();if(!name||Array.from(name).length>12||/[\u0000-\u001f\u007f]/.test(name))throw Error('이름은 1~12자로 입력해주세요.');const p=calc(date),s=C.stems[p.stem],ad=mode==='adoption';return{name,date,mode,calc:p,kind:ad?'함께 시작한 인연':'우리 아이 사주',title:ad?C.adoption[p.stem][0]:s[2],tag:ad?'함께한 날에 담긴 이야기':`${s[0]} · ${elementName[p.element]}의 기운`,paragraphs:ad?[C.adoption[p.stem][1],'이 풀이는 입양일에 의미를 담은 이야기이며, 아이의 타고난 성격을 판단하지 않습니다. 익숙해지는 속도를 존중하고 작은 일상을 함께 쌓아가세요.','집에 온 것은 작은 아이인데, 바뀌는 것은 집안 전체일지도 모릅니다.']:[s[3],C.branches[p.branch],s[4],s[5]]};}
function pair(p,date){const owner=calc(date);const delta=(owner.element-p.calc.element+5)%5, a=C.pairs[delta];const ad=p.mode==='adoption';return{kind:ad?'보호자와 인연 풀이':'보호자와 궁합',name:p.name,title:a[0],tag:`${elementName[p.calc.element]} · ${elementName[owner.element]}의 만남`,paragraphs:ad?[`함께 시작한 날과 보호자의 생일에 담긴 오행을 소재로 읽는 인연 이야기입니다. ${['닮은 리듬 속에서 편안함을 찾는 만남입니다.','일상에 온기와 활기를 더하는 만남입니다.','다른 속도를 이해하며 가까워지는 만남입니다.','기다림과 배려로 믿음을 쌓는 만남입니다.','보살핌 속에서 서로의 자리가 깊어지는 만남입니다.'][delta]}`,a[2],a[3]]:[a[1],a[2],a[3]],relation:delta};}
const branchNames=['자','축','인','묘','진','사','오','미','신','유','술','해'];
function basis(p){return `${p.label} 일간 · ${branchNames[p.branch]} 일지 · ${elementName[p.element]}의 기운`;}
function fullPet(input){const p=pet(input);if(p.mode==='birth'){const t=C.profiles[p.calc.stem];p.paragraphs=[t[0],t[1],t[2],C.branches[p.calc.branch],C.stems[p.calc.stem][5],t[3]];}else p.paragraphs.push('한 줄로, 태어난 날은 몰라도 함께 쌓아갈 이야기는 우리에게 있는 인연.');p.explanation=p.mode==='birth'?`${basis(p.calc)}을 바탕으로 기본 기질과 애정 표현을 읽었습니다. 일간은 그날의 중심 기운을 나타내는 천간이고, 일지는 일주의 지지입니다. 출생시간을 받지 않아 시주와 시간에 따른 해석은 제외합니다.`:'입양일은 출생 사주가 아니라 함께한 시작을 기념하는 날입니다. 이 날짜의 일주에 담긴 상징을 인연 이야기로 풀었습니다.';return p;}
function fullPair(p,date){const q=pair(p,date),o=calc(date);const story=C.relationshipStories[q.relation];q.paragraphs=p.mode==='adoption'?[q.paragraphs[0],C.adoption[p.calc.stem][1],story[1],C.pairs[q.relation][3],story[2]]:[story[0],`보호자는 ${C.ownerTraits[o.stem]}이고, 아이는 ${C.petTraits[p.calc.stem]}로 읽습니다.`,story[1],C.pairs[q.relation][3],story[2]];q.explanation=`${p.mode==='adoption'?'함께한 날':'아이'}: ${basis(p.calc)}. 보호자: ${basis(o)}. ${['같은 오행이 만나는 관계','아이 쪽 기운이 보호자 쪽 기운을 생하는 관계','아이 쪽 기운이 보호자 쪽 기운을 극하는 관계','보호자 쪽 기운이 아이 쪽 기운을 극하는 관계','보호자 쪽 기운이 아이 쪽 기운을 생하는 관계'][q.relation]}로 읽었습니다. 생은 북돋움, 극은 조율의 상징이며 좋은 관계와 나쁜 관계를 판정하는 점수는 아닙니다.`;return q;}
function friendPair(first,second){const a=pet(first),b=pet(second);const d=(b.calc.element-a.calc.element+5)%5,type=d===0?0:(d===1||d===4)?1:2;const f=C.friends[type],ad=a.mode==='adoption'||b.mode==='adoption';return{kind:ad?'강아지 친구와 인연':'강아지 친구와 궁합',name:`${a.name} · ${b.name}`,title:f[0],tag:`${elementName[a.calc.element]} · ${elementName[b.calc.element]}의 만남`,paragraphs:[ad?'생일 또는 함께한 날의 오행으로 읽는 두 아이의 인연 이야기입니다. 입양일을 사용한 아이의 타고난 성격을 의미하지는 않습니다.':f[1].split('. ').slice(0,2).join('. ')+'.',ad?'서로 다른 하루를 보내던 두 아이에게 함께 걸을 길이 생겼습니다. 가까워지는 속도보다 각자가 편안해지는 순간을 먼저 알아주는 인연이에요.':`첫 번째 아이는 ${C.petTraits[a.calc.stem]}, 두 번째 아이는 ${C.petTraits[b.calc.stem]}입니다.`,f[2],f[3],['한 줄로, 닮은 발걸음으로 각자의 하루에 편안히 머무는 친구.','한 줄로, 서로 다른 호기심을 나누며 함께할 세상을 넓히는 친구.','한 줄로, 같은 속도를 강요하지 않을 때 서로를 더 깊이 알아가는 친구.'][type]],explanation:`첫 번째 아이${a.mode==='adoption'?'의 입양일':''}: ${basis(a.calc)}. 두 번째 아이${b.mode==='adoption'?'의 입양일':''}: ${basis(b.calc)}. ${type===0?'같은 오행':type===1?'상생':'상극'}의 관계로 풀이합니다. 입력 순서를 바꾸어도 관계 유형은 같습니다. 이 풀이는 합사나 만남의 안전성을 판단하는 기준이 아닙니다.`,relation:type};}
const api={today,parseDate,calc,pet:fullPet,pair:fullPair,friends:friendPair};root.FortuneEngine=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
